// The review corrected distance symmetry and pixel Y conversion. Retain the
// original varied inputs, but validate these changed outputs independently.
fn review_rectangle_distance(rectangle: Rectangle2d, point: Vec2) {
    let local = rectangle.orientation_mat2().inverse() * (point - rectangle.center);
    let half = rectangle.size * 0.5;
    let corners = [Vec2::new(-half.x, -half.y), Vec2::new(-half.x, half.y),
        Vec2::new(half.x, half.y), Vec2::new(half.x, -half.y)];
    let mut distance = f32::INFINITY;
    for index in 0..4 {
        let start = corners[index];
        let edge = corners[(index + 1) % 4] - start;
        let t = ((local - start).dot(edge) / edge.length_squared()).clamp(0.0, 1.0);
        distance = distance.min(local.distance(start + edge * t));
    }
    let inside = local.abs().cmple(half).all();
    let expected = if inside { -distance } else { distance };
    let tolerance = 2e-5 * distance.max(1.0);
    assert!((rectangle.signed_distance_to_closest_edge(point) - expected).abs() <= tolerance);
    assert!((rectangle.distance_to_closest_edge(point) - expected.max(0.0)).abs() <= tolerance);
}
fn review_mouse_ray(mouse: Vec2, viewport: Vec2, inverse_projection: Mat4, inverse_view: Mat4) -> Ray {
    let ray = Ray::from_mouse_ss(mouse, viewport, inverse_projection, inverse_view);
    let world_to_clip = inverse_projection.inverse() * inverse_view.inverse();
    let expected = Vec2::new(mouse.x / viewport.x * 2.0 - 1.0, 1.0 - mouse.y / viewport.y * 2.0);
    let near = world_to_clip.project_point3(ray.origin);
    let far = world_to_clip.project_point3(ray.origin + ray.direction * 100.0);
    assert!((near.truncate() - expected).length() < 0.002, "near={near:?} expected={expected:?}");
    assert!((far.truncate() - expected).length() < 0.002, "far={far:?} expected={expected:?}");
    assert!((near.z - 1.0).abs() < 0.002);
    assert!((ray.direction.length() - 1.0).abs() < 1e-5);
    ray
}
